sys_ui_page.client_script:
$j(document).ready(function() {
    loadPDIList();
});

function loadPDIList() {
    var ga = new GlideAjax('PDIObserverAjax');
    ga.addParam('sysparm_name', 'getPDIData');

    ga.getXMLAnswer(function(answer) {
        var tbody = $j('#pdiTableBody');
        tbody.empty(); // Clear the "Loading data..." message

        if (!answer) {
            tbody.append('<tr><td colspan="5" style="text-align: center;">No data received from server.</td></tr>');
            return;
        }

        try {
            var pdiData = JSON.parse(answer);

            if (pdiData.length === 0) {
                tbody.append('<tr><td colspan="5" style="text-align: center;">No PDIs registered yet. Click "Add PDI" to start.</td></tr>');
                return;
            }

            var totalCount = pdiData.length;
            var onlineCount = 0;
            var offlineCount = 0;

            // Loop through each PDI and build the table row
            pdiData.forEach(function(pdi) {
                var statusBadge = '';

                if (pdi.status === 'Online') {
                    statusBadge = '<span class="label label-success">Online</span>';
                    onlineCount++;
                } else if (pdi.status === 'Offline') {
                    statusBadge = '<span class="label label-danger">Offline / Error</span>';
                    offlineCount++;
                } else {
                    statusBadge = '<span class="label label-warning">Pending Check</span>';
                }

                var rowHTML = '<tr>' +
                    '<td><strong>' + pdi.url + '</strong></td>' +
                    '<td>' + pdi.version + '</td>' +
                    '<td>' + statusBadge + '</td>' +
                    '<td>' + pdi.last_check + '</td>' +
                    '<td style="text-align: center;">' +
                        // Pass the sys_id to the ping function for later use
                        '<button class="btn btn-default btn-xs" title="Ping Now">' +
                            '<span class="glyphicon glyphicon-refresh"></span>' +
                        '</button>' +
                    '</td>' +
                '</tr>';

                tbody.append(rowHTML);
            });

            // Update Dashboard statistics
            $j('#statTotal').text(totalCount);
            $j('#statOnline').text(onlineCount);
            $j('#statOffline').text(offlineCount);

        } catch (ex) {
            console.error("JSON Parsing Error: ", ex);
            tbody.append('<tr><td colspan="5" style="text-align: center; color: red;">Error processing PDI data. Check console logs.</td></tr>');
        }
    });
}

function saveNewPDI() {
    // 1. Get data from the form
    var url = $j('#pdiUrl').val().trim();
    var pEmail = $j('#portalEmail').val().trim();
    var pPass = $j('#portalPass').val();
    var iUser = $j('#instanceUser').val().trim();
    var iPass = $j('#instancePass').val();

    // 2. Perform basic validation
    if (!url) {
        alert("Please provide the Instance URL!");
        $j('#pdiUrl').focus();
        return;
    }

    // 3. Disable the button to prevent multiple clicks
    var btn = $j('#btnSavePDI');
    btn.prop('disabled', true).text('Saving...');

    // 4. Initialize GlideAjax
    var ga = new GlideAjax('PDIObserverAjax');
    ga.addParam('sysparm_name', 'registerNewPDI');

    // 5. Pass parameters to the server
    ga.addParam('sysparm_url', url);
    ga.addParam('sysparm_p_email', pEmail);
    ga.addParam('sysparm_p_pass', pPass);
    ga.addParam('sysparm_i_user', iUser);
    ga.addParam('sysparm_i_pass', iPass);

    // 6. Handle the server response
    ga.getXMLAnswer(function(answer) {
        btn.prop('disabled', false).text('Save Configuration');

        if (answer && answer.indexOf('SUCCESS') > -1) {
            $j('#addPdiModal').modal('hide');
            $j('#pdiForm')[0].reset();

            // Reload the page to show the new record in the table
            window.location.reload(); 
        } else {
            alert("An error occurred while saving the PDI: " + answer);
        }
    });
}
